fn main() -> i64 {
    match read_file("./data/tokens.txt") {
        Ok(text) => {
            let line = str_trim(text)
            let toks = str_split(line, ",")
            let d = dict_new()
            for i in 0..len(toks) {
                if str_len(toks[i]) > 0 {
                    dict_inc(d, toks[i])
                }
            }
            let keys = dict_keys(d)
            let best = ""
            let best_c = -1
            let second = ""
            let second_c = -1
            for i in 0..len(keys) {
                let k = keys[i]
                let c = dict_get_or(d, k, 0)
                if c > best_c {
                    second = best
                    second_c = best_c
                    best = k
                    best_c = c
                } else {
                    if c > second_c {
                        second = k
                        second_c = c
                    }
                }
            }
            match write_file("./out/answer.txt", second + "\n") {
                Ok(_) => 0
                Err(e) => {
                    eprintln("cannot write: {e}")
                    1
                }
            }
        }
        Err(e) => {
            eprintln("cannot read: {e}")
            2
        }
    }
}
